private void OnTriggerEnter(Collider other)
{
    // Start boss fight upon contact with player
    if (!_bossFightStarted && other.gameObject.name == "Player")
    {
        _bossFightStarted = true;
        _healthbarUI.SetActive(true);
        _bunnyAnimator.SetBool("waiting", false);

        Debug.Log("Start Boss Coroutine");
        StartCoroutine(ThrowRocks());
    }
